const r = $input.first().json.body || $input.first().json;
const lead = r.lead || {};
const esc = s => String(s ?? '').replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const rows = [['Name', lead.name], ['Phone', lead.phone], ['Email', lead.email], ['Interested in', lead.interest], ['Budget', lead.budget], ['Timeline', lead.timeline], ['Best callback time', lead.preferred_callback_time], ['Outcome', lead.outcome], ['Next step', lead.next_step], ['Channel', r.channel], ['Caller ID', r.caller], ['Duration (s)', r.duration]].filter(x => x[1]);
const transcript = (r.transcript || []).map(t => (t.role === 'user' ? 'Caller: ' : 'Agent: ') + t.text).join('\n');
const html = `<h2>${esc(lead.summary)}</h2><table cellpadding="4">${rows.map(x => `<tr><td><b>${esc(x[0])}</b></td><td>${esc(x[1])}</td></tr>`).join('')}</table><h3>Transcript</h3><pre style="white-space:pre-wrap">${esc(transcript)}</pre>`;
return [{ json: { subject: `[${r.company || 'Voice agent'}] New ${lead.outcome || 'lead'}: ${lead.name || r.caller || 'unknown caller'}`, html } }];
